# Role-only receipts: establish who the person is, nothing about a political mechanism (same convention as the pilot case files).
for _id,_txt in [('brad-jacobs','The reviewed profile establishes Jacobs as the founder and executive behind XPO, its GXO and RXO spin-offs and QXO. This is a role and business-history fact; it does not establish any political mechanism.'),
 ('lu-xiangyang','The reviewed profile identifies Lu as an early BYD investor and co-founder alongside his cousin Wang Chuanfu. This is a role and identity fact; it does not establish any political mechanism.')]:
 if not P[_id]['support']:
  _c=P[_id]['counter'][0]
  P[_id]['support']=[dict(text=_txt,source=_c['source'],url=_c['url'],date=_c['date'],kind='Role and identity only; not evidence of a mechanism',access=_c['access'])]
_prev=set()  # entries already authored in waves 1-20 keep their existing review
for _f in sorted((ROOT/'data/review-batches').glob('0[01]*.json')):
 _prev|=set(json.loads(_f.read_text())['profiles'])
for _k in list(P):
 if _k in _prev:P.pop(_k);R.pop(_k,None)
import re as _re
for _v in P.values():  # every narrow no-strong review must say it is not an exoneration
 if _v['status']=='no-strong' and not _re.search('comprehensive|exoneration|absence',_v['limitations'],_re.I):_v['limitations']=_v['limitations'].rstrip()+' This is a narrow review, not an exoneration.'
ids={p['id'] for p in json.loads((ROOT/'data/billionaires.json').read_text())['people']}
assert set(P)<=ids
(ROOT/'data/review-batches/033.json').write_text(json.dumps(dict(profiles=P,rubrics=R),ensure_ascii=False,indent=2)+'\n')
print(len(P),'authored reviews;',len(R),'rubrics')
